import pytest
from solution import masquer_email

def test_masque():
    assert masquer_email('alice@exemple.fr') == 'a***@exemple.fr'
    assert masquer_email('b@x.org') == 'b***@x.org'

def test_invalide():
    for e in ['sansarobase', '@domaine.fr', 'a@b@c']:
        with pytest.raises(ValueError):
            masquer_email(e)

import pytest
from solution import lire_tlv

def test_simple():
    assert lire_tlv(bytes.fromhex('5A0412345678')) == [(0x5A, bytes.fromhex('12345678'))]

def test_etiquette_2_octets_et_suite():
    assert lire_tlv(bytes.fromhex('9F02020001 8401AA')) == [(0x9F02, b'\x00\x01'), (0x84, b'\xaa')]

def test_longueur_81():
    v = bytes(200)
    assert lire_tlv(bytes([0x70, 0x81, 200]) + v) == [(0x70, v)]

def test_tronque():
    with pytest.raises(ValueError):
        lire_tlv(bytes.fromhex('5A0412'))
